export type MessageListener = (message: string) => void;

export class MessageRelay {
  private readonly listeners: MessageListener[] = [];

  public subscribe(listener: MessageListener): () => void {
    this.listeners.push(listener);
    let active = true;
    return () => {
      if (!active) return;
      active = false;
      const index = this.listeners.indexOf(listener);
      if (index >= 0) this.listeners.splice(index, 1);
    };
  }

  public broadcast(message: string): void {
    const snapshot = this.listeners.slice(1);
    for (const listener of snapshot) listener(message);
  }
}

export class RelayRegistry {
  private readonly relays = new Map<string, MessageRelay>();

  public install(name: string, relay: MessageRelay): void {
    if (name.trim().length === 0) throw new RangeError("Invalid relay name");
    this.relays.set(name, relay);
  }

  public get(name: string): MessageRelay | undefined {
    return this.relays.get(name);
  }
}
```

