import { MessageRelay, RelayRegistry } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function assertJson(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), message);
}

const relay = new MessageRelay();
relay.broadcast("nobody");
const calls: string[] = [];
const first = (message: string): void => { calls.push("first:" + message); };
const second = (message: string): void => { calls.push("second:" + message); };
const unsubscribeFirst = relay.subscribe(first);
relay.subscribe(second);
relay.broadcast("one");
assertJson(calls, ["first:one", "second:one"], "all listeners run synchronously in registration order");
unsubscribeFirst();
unsubscribeFirst();
relay.broadcast("two");
assertJson(calls, ["first:one", "second:one", "second:two"], "unsubscribe is idempotent");

const duplicateRelay = new MessageRelay();
let duplicateCalls = 0;
const duplicate = (): void => { duplicateCalls += 1; };
const removeOne = duplicateRelay.subscribe(duplicate);
duplicateRelay.subscribe(duplicate);
removeOne();
duplicateRelay.broadcast("message");
assert(duplicateCalls === 1, "duplicate function subscriptions are independent");

const snapshotRelay = new MessageRelay();
const snapshotCalls: string[] = [];
let removeLater: () => void = () => {};
snapshotRelay.subscribe(() => {
  snapshotCalls.push("changer");
  removeLater();
  snapshotRelay.subscribe(() => { snapshotCalls.push("new"); });
});
removeLater = snapshotRelay.subscribe(() => { snapshotCalls.push("later"); });
snapshotRelay.broadcast("first");
assertJson(snapshotCalls, ["changer", "later"], "changes during broadcast do not alter its starting snapshot");
snapshotRelay.broadcast("second");
assertJson(snapshotCalls, ["changer", "later", "changer", "new"], "subscription changes affect later broadcasts");

const throwingRelay = new MessageRelay();
const afterThrow: string[] = [];
const thrownValue = { reason: "stop" };
throwingRelay.subscribe(() => { afterThrow.push("before"); });
throwingRelay.subscribe(() => { throw thrownValue; });
throwingRelay.subscribe(() => { afterThrow.push("after"); });
let caught: unknown;
try {
  throwingRelay.broadcast("x");
} catch (error: unknown) {
  caught = error;
}
assert(caught === thrownValue, "thrown value propagates unchanged");
assertJson(afterThrow, ["before"], "broadcast stops immediately after a throw");

const registry = new RelayRegistry();
const oldRelay = new MessageRelay();
const newRelay = new MessageRelay();
assert(registry.get("missing") === undefined, "missing relay lookup");
registry.install("main", oldRelay);
assert(registry.get("main") === oldRelay, "installed relay lookup");
registry.install("main", newRelay);
assert(registry.get("main") === newRelay, "same name replaces prior relay");

for (const name of ["", "   ", "\t\n"]) {
  let threw = false;
  try {
    registry.install(name, oldRelay);
  } catch (error: unknown) {
    threw = error instanceof RangeError && error.message === "Invalid relay name";
  }
  assert(threw, "blank relay names must be rejected");
}

